package com.vahotel.service;import com.vahotel.repo.ReservationRepository;import java.time.LocalDate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class ReservationExpiryJob {private final ReservationRepository repo;public ReservationExpiryJob(ReservationRepository r){repo=r;}@Scheduled(fixedDelay=60000,initialDelay=10000) @Transactional public void expire(){LocalDate today=LocalDate.now(java.time.ZoneId.of("Asia/Manila"));repo.findAll().stream().filter(r->("PENDING".equals(r.getStatus())||"PAID".equals(r.getStatus())||"CANCELLATION_REQUESTED".equals(r.getStatus()))&&!r.getCheckIn().isAfter(today)).forEach(r->{r.setStatus("EXPIRED");repo.save(r);});}}
